def forward(groups):
    value_kb = float(groups[0])
    canonical_bytes = round(value_kb * 1024)
    return {'stored': [canonical_bytes], 'layout': []}

def inverse(record):
    canonical_bytes = int(record['stored'][0])
    value_kb = canonical_bytes / 1024
    return f'{value_kb:.1f} KB'
